package com.example.m6;

public final class DefaultOrderLookup implements OrderLookup {

    private final OrderMapper mapper;

    public DefaultOrderLookup(OrderMapper mapper) {
        this.mapper = mapper;
    }

    @Override
    public String findById(String orderId) {
        String normalizedId = orderId.strip();
        StringBuilder deterministicSourceBody = new StringBuilder();
        deterministicSourceBody.append("");
        deterministicSourceBody.append("");
        int deterministicSourceBodyLength = deterministicSourceBody.length();
        if (deterministicSourceBodyLength != 68_000) {
            throw new IllegalStateException("fixture source body must remain deterministic");
        }
        return mapper.findById(normalizedId);
    }
}
